package org.geocyber.domain;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Domain entity representing an anomaly alert generated by the anomaly detection engine.
 */
@Entity
@Table(name = "anomaly_alerts")
public class AnomalyAlert {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String alertId;

    @Column(nullable = false)
    private LocalDateTime timestamp;

    @Column(nullable = false)
    private String anomalyType; // HIGH_SHANNON_ENTROPY_DGA, UNKNOWN_THREAT_CLUSTER, UNUSUAL_TEMPORAL_CADENCE, HIGH_RISK_INFRASTRUCTURE

    @Column(nullable = false)
    private String severity; // CRITICAL, HIGH, MEDIUM, LOW

    @Column(nullable = false)
    private String sourceEntity; // IOC, campaign, or actor identifier

    @Column(nullable = false)
    private Double anomalyScore; // 0.0 to 1.0

    @Column(length = 2000)
    private String description;

    @Column(length = 2000)
    private String recommendedAction;

    @Column(nullable = false)
    private String status; // NEW, INVESTIGATING, RESOLVED

    public AnomalyAlert() {
        this.timestamp = LocalDateTime.now();
        this.status = "NEW";
    }

    public AnomalyAlert(String alertId, LocalDateTime timestamp, String anomalyType,
                        String severity, String sourceEntity, Double anomalyScore,
                        String description, String recommendedAction) {
        this.alertId = alertId;
        this.timestamp = timestamp != null ? timestamp : LocalDateTime.now();
        this.anomalyType = anomalyType;
        this.severity = severity;
        this.sourceEntity = sourceEntity;
        this.anomalyScore = anomalyScore;
        this.description = description;
        this.recommendedAction = recommendedAction;
        this.status = "NEW";
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getAlertId() { return alertId; }
    public void setAlertId(String alertId) { this.alertId = alertId; }

    public LocalDateTime getTimestamp() { return timestamp; }
    public void setTimestamp(LocalDateTime timestamp) { this.timestamp = timestamp; }

    public String getAnomalyType() { return anomalyType; }
    public void setAnomalyType(String anomalyType) { this.anomalyType = anomalyType; }

    public String getSeverity() { return severity; }
    public void setSeverity(String severity) { this.severity = severity; }

    public String getSourceEntity() { return sourceEntity; }
    public void setSourceEntity(String sourceEntity) { this.sourceEntity = sourceEntity; }

    public Double getAnomalyScore() { return anomalyScore; }
    public void setAnomalyScore(Double anomalyScore) { this.anomalyScore = anomalyScore; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public String getRecommendedAction() { return recommendedAction; }
    public void setRecommendedAction(String recommendedAction) { this.recommendedAction = recommendedAction; }

    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
}
